<?php require __DIR__.'/layout.php';?><h1>Admin dashboard</h1><div class="stats"><article>Sales<strong><?=money($sales)?></strong></article><article>Products<strong><?=count($ps)?></strong></article><article>Recent orders<strong><?=count($os)?></strong></article></div><section class="form"><h2>Add product</h2><form method="post" action="admin/product"><?=csrf_input()?><label>Name<input name="name" required></label><label>Price<input type="number" min="0" step=".01" name="price" required></label><label>Stock<input type="number" min="0" name="stock" required></label><label>Description<textarea name="description"></textarea></label><button>Save product</button></form></section><h2>Orders</h2><?php foreach($os as $o):?><article class="order"><b><?=e($o['order_number'])?></b> <?=e($o['customer_name'])?> · <?=money($o['total'])?><form method="post" action="admin/status"><?=csrf_input()?><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending','processing','shipped','completed','cancelled'] as $st):?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button>Update</button></form></article><?php endforeach;?></main></body></html>